export interface GenerationMetadata {
    generatorVersion: string;
    sdkVersion: string;
}

export const GENERATOR_VERSION = '1.0.0';

export const DEFAULT_GENERATION_METADATA: GenerationMetadata = {
    generatorVersion: GENERATOR_VERSION,
    sdkVersion: 'unknown',
};

export function withSdkVersion(metadata: GenerationMetadata, sdkVersion: string): GenerationMetadata {
    return { ...metadata, sdkVersion };
}

export function autoGeneratedHeader(
    route: string,
    metadata: GenerationMetadata = DEFAULT_GENERATION_METADATA,
): string[] {
    return [
        '// <auto-generated>',
        `// 由 ${route} 生成。`,
        `// 生成器版本：${metadata.generatorVersion}；HarmonyOS SDK：${metadata.sdkVersion}`,
        '// 生成器输入：HarmonyOS SDK .d.ts → astParser → ComponentInfo → 本生成器',
        '// </auto-generated>',
    ];
}

export interface RequiredUsingsOptions {
    namespace?: string;
    arkuiTypes?: Iterable<string>;
}

export function requiredUsings(body: string, options: RequiredUsingsOptions = {}): string[] {
    // UTF-8 name constants use ReadOnlySpan<byte>.ToArray(), not System.Linq.
    const normalized = body.replace(/"(?:\\.|[^"\\])*"u8\.ToArray\(\)/g, '');
    const usings: string[] = [];

    if (/\b(?:IntPtr|UIntPtr|Flags|ReadOnlySpan|Span|GC|InvalidOperationException)\b/.test(normalized)) {
        usings.push('using System;');
    }
    if (/\.(?:Cast|Distinct|Except|GroupBy|OrderBy|OrderByDescending|Select|SelectMany|SequenceEqual|Skip|Take|ToArray|ToDictionary|ToList|Union|Where)\s*\(/.test(normalized)
        || /\bEnumerable\./.test(normalized)) {
        usings.push('using System.Linq;');
    }
    if (/\b(?:Marshal|LibraryImport|MarshalAs|UnmanagedCallersOnly|DllImport)\b/.test(normalized)) {
        usings.push('using System.Runtime.InteropServices;');
    }
    if (/(?<!System\.Text\.)\b(?:Encoding|StringBuilder|StringWriter|StringReader)\b/.test(normalized)) {
        usings.push('using System.Text;');
    }
    if (/\bTask(?:<|\b)/.test(normalized)) {
        usings.push('using System.Threading.Tasks;');
    }
    if (/\b(?:NodeApi|NativeNodeApi|NativeValue|Napi\w+|napi_\w+|HiLog|ValueConverter|(?:Promise|Callback)TaskBridge|INapiRecord)\b/.test(normalized)) {
        usings.push('using HarmonyOS.Interop;');
    }

    const namespace = options.namespace;
    if (namespace && namespace !== 'HarmonyOS.ArkUI') {
        const arkuiTypes = new Set(options.arkuiTypes ?? []);
        arkuiTypes.add('ArkUIComponentBase');
        arkuiTypes.add('ArkUIAttributeBase');
        const referencesArkuiType = [...arkuiTypes].some(name =>
            new RegExp(`(?<![.\\w])${name}\\b`).test(normalized));
        if (referencesArkuiType) usings.push('using HarmonyOS.ArkUI;');
    }
    if (/\[Description(?:\(|\s)/.test(normalized)) {
        usings.push('using System.ComponentModel;');
    }

    return usings;
}
